namespace sv_f0fca231164a43aeb035ab39d310e120.Services;

public class AppointmentService
{
    private static readonly List<string> Doctors = ["Dr. Smith", "Dr. Johnson", "Dr. Williams", "Dr. Brown"];

    private static readonly List<string> TimeSlots = ["9:00 AM", "9:30 AM", "10:00 AM", "10:30 AM", "11:00 AM", "1:00 PM", "1:30 PM", "2:00 PM", "2:30 PM", "3:00 PM"];

    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(Doctors);
    }

    public Task<List<string>> GetAvailableTimeSlotsAsync(string doctor, DateOnly date)
    {
        // Stub: return all time slots regardless of doctor/date
        return Task.FromResult(new List<string>(TimeSlots));
    }

    /// <summary>
    /// Validates patient/appointment data with server-side business rules.
    /// Returns a dictionary of field name -> error messages.
    /// </summary>
    public Task<Dictionary<string, List<string>>> ValidatePatientAsync(
        string email,
        string insuranceProvider,
        string doctor,
        string timeSlot)
    {
        var errors = new Dictionary<string, List<string>>();

        // Rule: outstanding balance check
        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors[nameof(email)] = ["Account has outstanding balance"];
        }

        // Rule: self-pay not accepted by certain doctors
        if (insuranceProvider == "None" && doctor == "Dr. Smith")
        {
            errors[nameof(doctor)] = ["Selected doctor does not accept self-pay patients"];
        }

        // Rule: race condition on time slot
        if (timeSlot == "10:00 AM")
        {
            errors[nameof(timeSlot)] = ["This slot is no longer available"];
        }

        return Task.FromResult(errors);
    }
}

using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Forms;

namespace sv_f0fca231164a43aeb035ab39d310e120.Components;

public class CustomValidator : ComponentBase
{
    [CascadingParameter]
    private EditContext? EditContext { get; set; }

    private ValidationMessageStore? messageStore;

    protected override void OnInitialized()
    {
        messageStore = new ValidationMessageStore(EditContext!);
        EditContext!.OnValidationRequested += (s, e) => messageStore.Clear();
        EditContext!.OnFieldChanged += (s, e) => messageStore.Clear(e.FieldIdentifier);
    }

    public void DisplayErrors(Dictionary<string, List<string>> errors)
    {
        foreach (var (field, messages) in errors)
        {
            foreach (var message in messages)
            {
                messageStore!.Add(EditContext!.Field(field), message);
            }
        }
        EditContext!.NotifyValidationStateChanged();
    }

    public void ClearErrors()
    {
        messageStore?.Clear();
        EditContext?.NotifyValidationStateChanged();
    }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_f0fca231164a43aeb035ab39d310e120.Services
@inject AppointmentService AppointmentService

<h1>Book an Appointment</h1>

<EditForm EditContext="editContext" OnValidSubmit="HandleSubmit">
    <DataAnnotationsValidator />
    <CustomValidator @ref="customValidator" />

    <h2>Step 1: Patient Information</h2>

    <div class="mb-3">
        <label>Patient Name:</label>
        <InputText @bind-Value="model.PatientName" class="form-control" />
        <ValidationMessage For="() => model.PatientName" />
    </div>

    <div class="mb-3">
        <label>Email:</label>
        <InputText @bind-Value="model.Email" class="form-control" />
        <ValidationMessage For="() => model.Email" />
    </div>

    <div class="mb-3">
        <label>Phone:</label>
        <InputText @bind-Value="model.Phone" class="form-control" />
        <ValidationMessage For="() => model.Phone" />
    </div>

    <div class="mb-3">
        <label>Insurance Provider:</label>
        <InputSelect @bind-Value="model.InsuranceProvider" class="form-control">
            <option value="">-- Select --</option>
            <option value="Aetna">Aetna</option>
            <option value="BlueCross">BlueCross</option>
            <option value="Cigna">Cigna</option>
            <option value="UnitedHealth">UnitedHealth</option>
            <option value="None">None</option>
        </InputSelect>
        <ValidationMessage For="() => model.InsuranceProvider" />
    </div>

    @if (!showStep2)
    {
        <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">Next</button>
    }

    @if (showStep2)
    {
        <h2>Step 2: Appointment Details</h2>

        <div class="mb-3">
            <label>Preferred Doctor:</label>
            <InputSelect @bind-Value="model.Doctor" class="form-control" @bind:after="OnDoctorChanged">
                <option value="">-- Select --</option>
                @foreach (var doctor in doctors)
                {
                    <option value="@doctor">@doctor</option>
                }
            </InputSelect>
            <ValidationMessage For="() => model.Doctor" />
        </div>

        <div class="mb-3">
            <label>Date:</label>
            <InputDate @bind-Value="model.AppointmentDate" class="form-control" @bind:after="OnDateChanged" />
            <ValidationMessage For="() => model.AppointmentDate" />
        </div>

        <div class="mb-3">
            <label>Time Slot:</label>
            <InputSelect @bind-Value="model.TimeSlot" class="form-control">
                <option value="">-- Select --</option>
                @foreach (var slot in timeSlots)
                {
                    <option value="@slot">@slot</option>
                }
            </InputSelect>
            <ValidationMessage For="() => model.TimeSlot" />
        </div>

        <div class="mb-3">
            <label>Reason for Visit:</label>
            <InputTextArea @bind-Value="model.ReasonForVisit" class="form-control" rows="4" />
            <ValidationMessage For="() => model.ReasonForVisit" />
        </div>

        <button type="button" class="btn btn-secondary me-2" @onclick="CheckAvailability" disabled="@isChecking">
            @(isChecking ? "Checking..." : "Check Availability")
        </button>
        <button type="submit" class="btn btn-success" disabled="@(!availabilityConfirmed)">
            Book Appointment
        </button>

        @if (availabilityConfirmed)
        {
            <div class="alert alert-success mt-3">Availability confirmed! You may submit.</div>
        }
    }
</EditForm>

@if (submitted)
{
    <div class="alert alert-success mt-3">
        <strong>Appointment booked successfully!</strong>
    </div>
}

@code {
    private EditContext? editContext;
    private AppointmentModel model = new();
    private CustomValidator? customValidator;

    private List<string> doctors = [];
    private List<string> timeSlots = [];

    private bool showStep2;
    private bool isChecking;
    private bool availabilityConfirmed;
    private bool submitted;

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(model);
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Validate step 1 fields only
        var isValid = true;
        var step1Fields = new[] { nameof(model.PatientName), nameof(model.Email), nameof(model.Phone), nameof(model.InsuranceProvider) };

        editContext!.Validate();
        foreach (var field in step1Fields)
        {
            if (editContext.GetValidationMessages(editContext.Field(field)).Any())
            {
                isValid = false;
            }
        }

        if (isValid)
        {
            showStep2 = true;
        }
    }

    private async Task OnDoctorChanged()
    {
        availabilityConfirmed = false;
        if (!string.IsNullOrEmpty(model.Doctor) && model.AppointmentDate.HasValue)
        {
            timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
                model.Doctor, DateOnly.FromDateTime(model.AppointmentDate.Value));
        }
    }

    private async Task OnDateChanged()
    {
        availabilityConfirmed = false;
        if (!string.IsNullOrEmpty(model.Doctor) && model.AppointmentDate.HasValue)
        {
            timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
                model.Doctor, DateOnly.FromDateTime(model.AppointmentDate.Value));
        }
    }

    private async Task CheckAvailability()
    {
        customValidator?.ClearErrors();
        availabilityConfirmed = false;
        isChecking = true;

        // Validate step 2 fields via DataAnnotations first
        var valid = editContext!.Validate();
        if (!valid)
        {
            isChecking = false;
            return;
        }

        // Server-side business rule validation
        var errors = await AppointmentService.ValidatePatientAsync(
            model.Email!,
            model.InsuranceProvider!,
            model.Doctor!,
            model.TimeSlot!);

        if (errors.Count > 0)
        {
            // Map service field names to model field names
            var mappedErrors = new Dictionary<string, List<string>>();
            foreach (var (key, messages) in errors)
            {
                var fieldName = key switch
                {
                    "email" => nameof(model.Email),
                    "doctor" => nameof(model.Doctor),
                    "timeSlot" => nameof(model.TimeSlot),
                    _ => key
                };
                mappedErrors[fieldName] = messages;
            }
            customValidator!.DisplayErrors(mappedErrors);
        }
        else
        {
            availabilityConfirmed = true;
        }

        isChecking = false;
    }

    private void HandleSubmit()
    {
        submitted = true;
    }
}

using System.ComponentModel.DataAnnotations;

namespace sv_f0fca231164a43aeb035ab39d310e120.Models;

public class AppointmentModel : IValidatableObject
{
    [Required(ErrorMessage = "Patient name is required.")]
    public string? PatientName { get; set; }

    [Required(ErrorMessage = "Email is required.")]
    [EmailAddress(ErrorMessage = "Invalid email format.")]
    public string? Email { get; set; }

    [Required(ErrorMessage = "Phone is required.")]
    public string? Phone { get; set; }

    [Required(ErrorMessage = "Insurance provider is required.")]
    public string? InsuranceProvider { get; set; }

    [Required(ErrorMessage = "Doctor selection is required.")]
    public string? Doctor { get; set; }

    [Required(ErrorMessage = "Appointment date is required.")]
    public DateTime? AppointmentDate { get; set; }

    [Required(ErrorMessage = "Time slot is required.")]
    public string? TimeSlot { get; set; }

    [Required(ErrorMessage = "Reason for visit is required.")]
    [MaxLength(500, ErrorMessage = "Reason cannot exceed 500 characters.")]
    public string? ReasonForVisit { get; set; }

    public IEnumerable<ValidationResult> Validate(ValidationContext validationContext)
    {
        if (AppointmentDate.HasValue && AppointmentDate.Value.Date <= DateTime.Today)
        {
            yield return new ValidationResult(
                "Appointment date must be in the future.",
                [nameof(AppointmentDate)]);
        }
    }
}

