@code {
    private EditContext? editContext;
    private AppointmentModel model = new();
    private CustomValidator? customValidator;

    private List<string> doctors = [];
    private List<string> timeSlots = [];

    private bool showStep2;
    private bool isChecking;
    private bool availabilityConfirmed;
    private bool submitted;

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(model);
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Validate step 1 fields only
        var isValid = true;
        var step1Fields = new[] { nameof(model.PatientName), nameof(model.Email), nameof(model.Phone), nameof(model.InsuranceProvider) };

        editContext!.Validate();
        foreach (var field in step1Fields)
        {
            if (editContext.GetValidationMessages(editContext.Field(field)).Any())
            {
                isValid = false;
            }
        }

        if (isValid)
        {
            showStep2 = true;
        }
    }

    private async Task OnDoctorChanged()
    {
        availabilityConfirmed = false;
        if (!string.IsNullOrEmpty(model.Doctor) && model.AppointmentDate.HasValue)
        {
            timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
                model.Doctor, DateOnly.FromDateTime(model.AppointmentDate.Value));
        }
    }

    private async Task OnDateChanged()
    {
        availabilityConfirmed = false;
        if (!string.IsNullOrEmpty(model.Doctor) && model.AppointmentDate.HasValue)
        {
            timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
                model.Doctor, DateOnly.FromDateTime(model.AppointmentDate.Value));
        }
    }

    private async Task CheckAvailability()
    {
        customValidator?.ClearErrors();
        availabilityConfirmed = false;
        isChecking = true;

        // Validate step 2 fields via DataAnnotations first
        var valid = editContext!.Validate();
        if (!valid)
        {
            isChecking = false;
            return;
        }

        // Server-side business rule validation
        var errors = await AppointmentService.ValidatePatientAsync(
            model.Email!,
            model.InsuranceProvider!,
            model.Doctor!,
            model.TimeSlot!);

        if (errors.Count > 0)
        {
            // Map service field names to model field names
            var mappedErrors = new Dictionary<string, List<string>>();
            foreach (var (key, messages) in errors)
            {
                var fieldName = key switch
                {
                    "email" => nameof(model.Email),
                    "doctor" => nameof(model.Doctor),
                    "timeSlot" => nameof(model.TimeSlot),
                    _ => key
                };
                mappedErrors[fieldName] = messages;
            }
            customValidator!.DisplayErrors(mappedErrors);
        }
        else
        {
            availabilityConfirmed = true;
        }

        isChecking = false;
    }

    private void HandleSubmit()
    {
        submitted = true;
    }
}
"}

